// swift-tools-version: 6.0
import PackageDescription

/// The Citadel client API, generated from the server's OpenAPI contract (`contract/openapi.json`, pinned to the
/// Citadel commit in `contract/CITADEL_REVISION`). The generated sources are committed and regenerated by
/// `make contract` (scripts/contract.sh) — no SPM build plugin, so consumers never resolve the generator and the
/// diff is reviewable. A static library: a plugin links every dependency into its own bundle. URLSession transport
/// only — no swift-nio (Docs/Topics/citadel-contract-format.md).
let package = Package(
    name: "QuestCitadelAPI",
    platforms: [.macOS(.v14)],
    products: [.library(name: "QuestCitadelAPI", type: .static, targets: ["QuestCitadelAPI"])],
    dependencies: [
        .package(url: "https://github.com/apple/swift-openapi-runtime", exact: "1.13.3"),
        .package(url: "https://github.com/apple/swift-openapi-urlsession", exact: "1.3.2"),
        .package(url: "https://github.com/apple/swift-http-types", exact: "1.8.0"),
    ],
    targets: [
        .target(
            name: "QuestCitadelAPI",
            dependencies: [
                .product(name: "OpenAPIRuntime", package: "swift-openapi-runtime"),
                .product(name: "OpenAPIURLSession", package: "swift-openapi-urlsession"),
                .product(name: "HTTPTypes", package: "swift-http-types"),
            ]
        )
    ],
    swiftLanguageModes: [.v6]
)
